Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

int n, t, rx, ry;
string lab[20], sci[20];
int mem[12][12][12][12][62];
int cap[250][250], par[250];
int dist[20][20], vis[20][20];

inline bool good(int x, int y){
	return 0 <= x && x < n && 0 <= y && y < n && lab[x][y] != 'Y' && lab[x][y] != 'Z';
}

void pre(){
	memset(dist, 0x3f, sizeof(dist));
	memset(vis, 0, sizeof(vis));
	dist[rx][ry] = 0;
	vis[rx][ry] = 1;
	queue<int> qx, qy;
	qx.push(rx);
	qy.push(ry);
	while(!qx.empty()){
		int x = qx.front(); qx.pop();
		int y = qy.front(); qy.pop();
		for(int k = 0; k < 4; k++){
			int nx = x + dx[k];
			int ny = y + dy[k];
			if(good(nx, ny) && !vis[nx][ny]){
				dist[nx][ny] = dist[x][y] + 1;
				vis[nx][ny] = 1;
				qx.push(nx);
				qy.push(ny);
			}
		}
	}
}

int dfs(int x0, int y0, int x1, int y1, int ptr){
	if(ptr > t)return 0;
	int &ret = mem[x0][y0][x1][y1][ptr];
	if(ret != -1)return ret;
	if(x0 == x1 && y0 == y1)return dist[x0][y0] >= ptr;
	if(dist[x0][y0] <= ptr)return ret = 0;
	for(int k = 0; k < 4; k++){
		int nx = x0 + dx[k];
		int ny = y0 + dy[k];
		if(good(nx, ny) && dfs(nx, ny, x1, y1, ptr + 1))return ret = 1;
	}
	return ret = 0;
}

bool fml(int s, int t){
	memset(par, -1, sizeof(par));
	par[s] = -2;
	queue<int> qu;
	qu.push(s);
	while(!qu.empty()){
		int v = qu.front(); qu.pop();
		for(int i = s; i <= t; i++){
			if(par[i] == -1 && cap[v][i] > 0){
				par[i] = v;
				qu.push(i);
			}
		}
	}
	return par[t] != -1;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout<<setprecision(32);

	cin>>n>>t;
	for(int i = 0; i < n; i++){
		cin>>sci[i];
	}
	for(int i = 0; i < n; i++){
		cin>>lab[i];
	}
	vector<pair<int, int> > pos;
	vector<int> lc, sc;
	for(int i = 0; i < n; i++){
		for(int j = 0; j < n; j++){
			if(sci[i][j] == 'Z'){
				rx = i;
				ry = j;
			}else if('0' <= sci[i][j] && sci[i][j] <= '9'){
				pos.push_back({i, j});
				lc.push_back(lab[i][j] - '0');
				sc.push_back(sci[i][j] - '0');
			}
		}
	}
	int m = pos.size();
	memset(cap, 0, sizeof(cap));
	for(int i = 0; i < m; i++){
		cap[0][i + 1] = sc[i];
		cap[m + 1 + i][2*m + 1] = lc[i];
	}
	pre();
	memset(mem, -1, sizeof(mem));
	for(int i = 0; i < m; i++){
		for(int j = 0; j < m; j++){
			if(dfs(pos[i].first, pos[i].second, pos[j].first, pos[j].second, 0)){
				// cout<<pos[i].first<<" "<<pos[i].second<<" "<<pos[j].first<<" "<<pos[j].second<<endl;
				cap[i + 1][m + 1 + j] = 1000;
			}
		}
	}
	int flow = 0;
	while(fml(0, 2*m + 1)){
		int t = 2*m + 1;
		int nflow = 1e6;
		while(par[t] >= 0){
			nflow = min(nflow, cap[par[t]][t]);
			t = par[t];
		}
		t = 2*m + 1;
		while(par[t] >= 0){
			cap[par[t]][t] -= nflow;
			cap[t][par[t]] += nflow;
			t = par[t];
		}
		flow += nflow;
	}
	cout<<flow;

	return 0;
}
